<script setup lang="ts">
import type {Scenario} from '../types';defineProps<{scenario:Scenario}>();const emit=defineEmits<{update:[key:keyof Scenario,value:any]}>();
function text(e:Event){return (e.target as HTMLInputElement).value}
</script>
<template><section class="panel"><header><h2>牌局参数</h2><span class="muted">金额使用同一单位</span></header><div class="fields"><label>仍在争夺底池的对手<select :value="scenario.opponents" @change="emit('update','opponents',Number(text($event)))"><option v-for="n in 8" :value="n">{{n}} 位</option></select></label><label>当前底池<input inputmode="decimal" type="text" :value="scenario.pot" @input="emit('update','pot',text($event))" placeholder="例如 100"></label><label>本次需补齐的跟注额<input inputmode="decimal" type="text" :value="scenario.call" @input="emit('update','call',text($event))" placeholder="无人下注填 0"></label><label>你的剩余筹码<input inputmode="decimal" type="text" :value="scenario.stack" @input="emit('update','stack',text($event))" placeholder="可留空"></label></div><p class="muted">底池含对手已下注，不含你将补齐的金额。跟注额不是对手下注总额。</p><details><summary>计算与决策设置</summary><label class="advanced">模拟预算<select :value="scenario.samples" @change="emit('update','samples',Number(text($event)))"><option :value="10000">10,000 次 · 快速</option><option :value="25000">25,000 次 · 标准</option><option :value="100000">100,000 次 · 精细</option></select></label><label class="checkbox"><input type="checkbox" :checked="scenario.closed" @change="emit('update','closed',($event.target as HTMLInputElement).checked)">跟注后不再下注，且没有边池</label><p class="muted">河牌单对手自动精确枚举，不使用模拟预算。此版本不计抽水。</p></details></section></template>
